import {allocationTotal,distributeAllocations,validAllocations} from './allocation-model.js';
import {sampleQuote} from './sample-quote.js';
import {policyArtwork} from './visuals.js';
import {premiumSummary,premiumBreakdown,money} from './premium-components.js';
import {reviewRow,reviewGroup,reviewSection,coverageContext,coverageOption,quotationAddon,actionBar as baseActionBar} from './insurance-components.js';
import {button, notice, sectionHeading, documentRow} from './ui.js';
import {createFormComponents} from './components.js';
import {icon} from './icons.js';
import {readDraft,saveDraft,clearDraft} from './draft.js';
import {classifications,specialisations,observedGpLimits,individualQuestions,organisationQuestions,supplementary,disclosureHtml,states} from './content.js';
import {insuranceApi} from './api.js';
import {configuration} from './catalog.js';
import {clinicRoute,resetClinicDependents} from './clinic-rules.js';
import {validateCoverage,validateQuotation,validatePersonal,validateDeclarations} from './validation.js';

const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const review=new URLSearchParams(location.search).get('review')==='1';
const samplePricing=review||new URLSearchParams(location.search).get('sample')==='1';
const currentQuote=()=>samplePricing?sampleQuote(data):null;
const data={classification:'',liability:'',start:'',email:'',promo:'',consent:false,allocations:{},clinic:'',ownership:'',locum:'',picAny:'',picOther:'',clinicLiability:'',nationality:'',otherNationality:'',clinicName:'',branchAgreement:false,pic:'',clinicCover:false,picCover:false,fullName:'',dob:'',nric:'',tin:'',practice:'',mobile:'',declaration:false,branches:[],answers:{},intent:'Buy now',payment:'',riskDetails:'',orgDetails:'',patients:'',revenue:''};
let stage=0, errors={}, maxStage=0, activeState=null;
let draftStorage;try{draftStorage=sessionStorage;}catch{}
if(!review&&!samplePricing){const draft=readDraft(draftStorage,data);if(draft){Object.assign(data,draft.data);stage=draft.stage;maxStage=draft.maxStage;}}
const persist=()=>{if(!review&&!samplePricing){const saved=saveDraft(draftStorage,data,stage,maxStage);const status=document.querySelector('#draft-status');if(status){status.textContent=saved?'Saved in this tab':'Progress could not be saved. Keep this page open.';status.dataset.state=saved?'saved':'error';}}};
const actionBar=(back='',forward='')=>!activeState?`<div class="premium-action-bar ${stage===0?'coverage-action-bar':''}"><div class="premium-action-inner">${stage>0?premiumSummary(currentQuote()):''}<div class="premium-navigation">${back}${forward}</div></div></div>`:baseActionBar(back,forward);
const stages=['Coverage','Quotation','Personal Particulars','Declaration','Summary'];
const next=(label='Next',action='next')=>button(label,{action,trailing:'arrow',disabled:action==='payment'&&!samplePricing,describedBy:action==='payment'?'payment-availability':''});
const back=()=>button('Back',{action:'back',variant:'quiet',leading:'back'});
const head=sectionHeading;
const {field,textarea,select,question,check,errorFor,attrs}=createFormComponents(()=>data,()=>errors);
const pidm=()=>`<div class="notice legal-notice">${icon('info',18)}<p>The benefit(s) payable under eligible certificate/ policy/ product is(are) protected by PIDM up to limits. Please refer to <a href="https://www.pidm.gov.my/pidm2022/media/downloads/Takaful-And-Insurance-Benefits-Protection-System-Brochure.pdf" target="_blank" rel="noopener">PIDM’s TIPS Brochure</a> or contact <a href="https://www.chubb.com/my-en/contact-us.html" target="_blank" rel="noopener">Chubb Insurance Malaysia Berhad</a> or PIDM (visit <a href="https://www.pidm.gov.my/en" target="_blank" rel="noopener">www.pidm.gov.my</a>).</p></div>`;
const dateText=s=>s?new Date(s+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'}):'—';
const endDate=()=>data.start?`${data.start.slice(0,4)}-12-31`:'';
function summary(){return `<section class="card side-section"><div class="side-title"><h3>Your coverage</h3>${stage?'<button type="button" class="link-btn" data-action="edit-coverage">Edit</button>':''}</div><dl class="summary-list"><div><dt>Classification</dt><dd id="summary-classification">${esc(data.classification)||'—'}</dd></div><div><dt>Limit Of Liability</dt><dd id="summary-liability">${esc(data.liability)||'—'}</dd></div><div><dt>Coverage period</dt><dd id="summary-period">${data.start?`${dateText(data.start)} – ${dateText(endDate())}`:'—'}</dd></div></dl></section>`;}
function sidebar(){return `<aside class="visual-side" aria-label="Policy information"><div class="rail-navigation"><div class="rail-product-header"><div class="rail-brand-art">${policyArtwork()}</div><p class="rail-product">Chubb Elite Medical<br>Malpractice Insurance</p></div><nav id="stepper" class="stepper" aria-label="Application progress"></nav></div><div class="rail-resource-card rail-video"><iframe title="DoctorShield medical indemnity video" src="https://iframe.videodelivery.net/cf4ec2a777fd4d95cc1d020eb58c2a93?poster=https%3A%2F%2Fmy-individualindemnity.doctorshield.com%2Fassets%2Foverlay.png" loading="lazy" allow="autoplay; encrypted-media; picture-in-picture; fullscreen" allowfullscreen></iframe></div><div class="rail-guide"><img src="assets/coverage-guide.png" alt="" width="100" height="112"><h3>Step by step<br>Purchase</h3><a class="btn primary small" href="https://my-individualindemnity.doctorshield.com/assets/DoctorShield_User_Guide.pdf" target="_blank" rel="noopener">Download Guide</a></div><div class="rail-resources"><button type="button" class="document-link" data-action="documents">${icon('file',18)}<span>Policy documents</span></button><a class="document-link" href="https://my-individualindemnity.doctorshield.com/assets/DoctorShield_User_Guide.pdf" target="_blank" rel="noopener">${icon('external',18)}<span>User guide</span></a></div></aside>`;}
function coverage(){return `<div class="card"><div class="card-body"><section class="flow-card" aria-label="Coverage details"><div class="fields">${select('classification','Classification',classifications,{full:true,hint:[17,18].includes(configuration(data)?.id)?'Professionals under this classification are restricted to 20 hours of work per week':configuration(data)?.id===13?'All dental procedures categorized under general dentistry are included. You may classify yourself as a General Dentist if you are permitted to perform these procedures through recognized special training or courses.':configuration(data)?.id===20?'Non-invasive elective topical enhancement of patient’s external appearance, including injections.”':''})}</div><div id="allocation-slot">${allocationTrigger()}</div><div class="fields field-gap">${select('liability','Limit Of Liability',configuration(data)?.limits||[],{full:true,hint:''})}</div></section><section class="form-section flow-card" aria-labelledby="coverage-period-title"><h2 id="coverage-period-title">${icon('calendar',18)}Coverage period</h2><div class="fields">${field('start','Insurance Start Date',{type:'date'})}<div class="field calculated-field"><span class="field-label" id="end-label">Insurance End Date</span><output id="end" for="start" aria-labelledby="end-label">${esc(data.end)||'—'}</output></div></div></section><section class="form-section flow-card" aria-labelledby="contact-information-title"><h2 id="contact-information-title">${icon('mail',18)}Contact information</h2><div class="fields">${field('email','Your Email',{type:'email',full:true})}</div><details class="optional-field" ${data.promo?'open':''}><summary>Promo Code <span class="optional">Optional</span></summary><div class="fields">${field('promo','Promo Code',{full:true})}</div></details></section><div class="consent-section">${check('consent','I have read, understood and agree to the <a href="https://my.doctorshield.com/terms-of-use" target="_blank" rel="noopener">terms and conditions,</a> <a href="https://my.doctorshield.com/privacy-policy" target="_blank" rel="noopener">privacy policy</a> and I meet all local regulation to practice my profession.')}${pidm()}</div><div id="form-status"></div></div>${actionBar('',next('Continue','calculate'))}</div>`;}
function allocationTrigger(){
 if(!configuration(data)?.specialist)return '';
 const selected=Object.entries(data.allocations).filter(([,v])=>v>0),names=configuration(data)?.specialisations||[];
 return `<section class="allocation-summary"><div class="allocation-trigger"><div><strong>Specialisations</strong><span>${selected.length} selected · ${total(data.allocations)}% allocated</span></div><button type="button" class="btn secondary small" data-action="allocations">${icon('edit',14)}${selected.length?'Edit':'Add'} details</button></div>${selected.length?'<dl class="allocation-facts">'+selected.map(([i,v])=>'<div><dt>'+esc(names[i])+'</dt><dd>'+v+'%</dd></div>').join('')+'</dl>':''}${errorFor('allocations')}</section>`;
}
function quotation(){const route=clinicRoute(data,!!configuration(data)?.clinic);const questions={clinic:'Do you own a clinic?',ownership:'Is it a Sole proprietor or partnership / sdn bhd?',locum:'Do you hire locums who sees new patients on their own?',picAny:'Are you a Person-In-Charge (PIC) for any clinic?',picOther:'Are you a Person-In-Charge (PIC) with another establishment?'};
 const addon=(type,title,text)=>{
 const preview=samplePricing?sampleQuote({clinicCover:true,picCover:true}).items.find(item=>item.label===(type==='clinic'?'Clinic Medical Malpractice Insurance':'PIC coverage'))?.amount:null;
 return quotationAddon({id:type+'Cover',kind:type,title,selected:!!data[type+'Cover'],description:text,price:preview,sample:samplePricing,details:type==='clinic'?select('clinicLiability','Clinic Limit Of Liability',configuration(data)?.limits||[],{full:true}):''});
 };
 const recommendations=route.questions.length?`<section class="quotation-addons" aria-labelledby="quotation-addons-title"><div class="quotation-addons-heading"><h2 id="quotation-addons-title">Recommended Add-On</h2><span class="optional">Optional coverage</span></div><div class="practice-questions">${route.questions.map(key=>question(key,questions[key],key==='ownership'?['Sole Proprietor','Partnership / Sdn Bhd']:['Yes','No'])).join('')}</div>${route.clinic||route.pic?'<div class="quotation-addon-list">'+(route.clinic?addon('clinic','Clinic Medical Malpractice Insurance',route.clinicText):'')+(route.pic?addon('pic','PIC coverage',route.picText):'')+'</div>':route.questions.every(key=>data[key])?'<p class="addon-result">No additional cover is recommended for these answers.</p>':'<p class="hint addon-guidance">Complete the practice questions to see your recommended add-ons.</p>'}</section>`:'';
 return `<div class="card"><div class="card-body">${coverageContext({classification:data.classification,liability:data.liability,period:data.start?dateText(data.start)+' – '+dateText(endDate()):''})}<div class="quote-total"><div><p class="label">${samplePricing?'Total Premium':'Individual indemnity premium'}</p><p class="hint">Inclusive of SST &amp; Stamp Duty</p></div><div class="quote-price"><span class="pending-amount">${samplePricing?money(currentQuote().final):'Not yet calculated'}</span></div></div>${data.start&&!samplePricing?`<p class="quote-note">This premium is pro-rated for the period ${dateText(data.start)} to ${dateText(endDate())}</p>`:''}${recommendations}<div class="notice legal-notice">${icon('check',18)}<p>Your Insurance comes with complimentary Automatic Reinstatement now</p></div><div class="divider"></div><fieldset><legend>How would you like to proceed?</legend><div class="choices">${['Buy now','Email me the Indicative Quotation and Policy Wording'].map(v=>`<label class="choice wide"><input type="radio" name="intent" value="${v}" ${data.intent===v?'checked':''}>${v}</label>`).join('')}</div></fieldset><div class="quote-documents"><button type="button" class="document-link" data-action="documents">${icon('file',18)}Policy documents${icon('chevron',16)}</button><p class="hint">Please refer to the Policy Wording for the full details of benefits, exclusions, terms and conditions.</p></div><div id="form-status"></div></div>${actionBar(back(),next())}</div>`;}
function personal(){return `<div class="card"><div class="card-body"><section class="flow-card" aria-label="Your details">${head('Your details','user')}<div class="fields">${field('fullName','Full Name as per IC',{full:true,placeholder:'Enter your full name'})}${field('dob','Date Of Birth',{type:'date'})}${configuration(data)?.nric?field('nric','NRIC Number'):''}${select('nationality','Nationality',['Malaysia','Singapore','Hongkong','Thailand','Philippines','Vietnam','Indonesia','Australia','Others'])}${data.nationality==='Others'?field('otherNationality','Country name'):''}${field('tin','Tax Tin Number',{optional:true})}</div></section><section class="flow-card" aria-label="Contact details">${head('Contact details','phone')}<div class="fields">${field('mobile','Mobile Number',{type:'tel',placeholder:'+60'})}${field('email','Email Address',{type:'email'})}</div></section><section class="flow-card" aria-label="Practice details">${head('Practice details','building')}<div class="fields">${data.clinicCover?field('clinicName','Clinic name (Sdn Bhd/Partnership)',{full:true}):''}${field('practice','Enter the primary location of Practice',{full:true,hint:''})}${configuration(data)?.patients?field('patients','No of Patients Served',{type:'number',optional:true}):''}${configuration(data)?.revenue?field('revenue','Income',{type:'number',optional:true}):''}</div>${data.clinicCover?`<details class="branch-disclosure disclosure" ${data.branches.length?'open':''}><summary>Add Clinic / Branch</summary><div class="disclosure-body"><p class="field-label">Include Other Branches Within The Same Holding Company At No Additional Cost</p><span class="badge">Complimentary</span><p class="hint">Note: This offer is only available for branches with with less than a total revenue of RM 5,000,000 per annum. Kindly contact our clients services if in doubt.</p><div>${data.branches.map((b,i)=>`<div class="branch"><div><strong>${esc(b.name)}</strong><p>${esc(b.address)}</p><p>${esc(b.phone)}</p></div><div class="branch-actions"><button type="button" class="btn secondary small" data-action="edit-branch" data-index="${i}">Edit</button><button type="button" class="btn secondary small" data-action="remove-branch" data-index="${i}">Remove</button></div></div>`).join('')}</div><button type="button" class="btn secondary" data-action="branch" ${data.branches.length>=4?'disabled':''}>${icon('plus',16)}Add Clinic / Branch</button><p class="hint">You can add up to 4 branches</p><p class="hint">* The combined revenue of all branches must be less than RM 5,000,000.</p></div></details>`:''}</section></div>${actionBar(back(),next())}</div>`;}
function declarations(){const org=!!data.clinicCover;const questions=org?organisationQuestions:individualQuestions;const risk=org?[0,1,2,3].some(i=>data.answers['qOrg'+i]==='Yes'):hasRisk();const detail=org?'orgDetails':'riskDetails';return `<div class="card"><div class="card-body"><p class="section-caption">${org?'Individual and medical establishment':'Individual practitioner'}</p><div class="declaration-questions">${questions.map((q,i)=>`<div class="declaration-item"><span class="question-number" aria-hidden="true">${String(i+1).padStart(2,'0')}</span>${question((org?'qOrg':'q')+i,q,!org&&i===0?['Agree','Disagree']:['Yes','No'])}</div>`).join('')}</div>${risk?`<div class="disclosure-detail">${textarea(detail,'Please provide details below')}</div>`:''}<div class="divider"></div><button type="button" class="link-btn" data-action="declaration">Important Notices to the Applicants</button>${check('declaration','By proceeding, you agree that you have complied with all local regulations pertaining to your profession and you have further agreed that you have read, understood and accepted to the <button type="button" class="link-btn" data-action="declaration">Declaration and Authorization</button>, <button type="button" class="link-btn" data-action="documents">Policy Wording</button>, <a href="https://thedoctorshield.ja.deals/privacy-policy" target="_blank" rel="noopener">Privacy Policy</a> and <button type="button" class="link-btn" data-action="documents">Product Disclosure Sheet</button> for this product.')}<div id="form-status"></div></div>${actionBar(back(),next())}</div>`;}
function hasRisk(){return data.answers.q0==='Disagree'||[1,2,3].some(i=>data.answers['q'+i]==='Yes');}
function reviewScreen(){
 const row=reviewRow,group=reviewGroup,section=reviewSection;
 const coverage=group('Individual Coverage',row('Plan name','Chubb Elite Medical Malpractice Insurance')+row('Classification',data.classification)+row('Limit Of Liability',data.liability)+row('Coverage period',dateText(data.start)+' to '+dateText(endDate()))+row('Auto Reinstatement','Complimentary Auto Reinstatement'))+
 (data.clinicCover||data.picCover?group('Recommended Add-On',(data.clinicCover?row('Clinic Medical Malpractice Insurance',data.clinicLiability):'')+(data.picCover?row('PIC coverage','Selected'):'')):'')+
 (configuration(data)?.specialist?group('Service Details',Object.entries(data.allocations).filter(([,v])=>Number(v)>0).map(([i,v])=>row(configuration(data).specialisations[i],v+'%')).join('')):'');
 const personal=group('Personal Particulars',row('Full Name as per IC',data.fullName)+row('Date Of Birth',dateText(data.dob))+(configuration(data)?.nric?row('NRIC Number',data.nric):'')+row('Nationality',data.nationality==='Others'?data.otherNationality:data.nationality)+(data.tin?row('Tax Tin Number',data.tin):''))+group('Contact details',row('Email Address',data.email)+row('Mobile Number',data.mobile));
 const practice=group('',(data.clinicCover?row('Clinic name (Sdn Bhd/Partnership)',data.clinicName):'')+row('Enter the primary location of Practice',data.practice)+(configuration(data)?.patients&&data.patients?row('No of Patients Served',data.patients):'')+(configuration(data)?.revenue&&data.revenue?row('Income',data.revenue):''))+
 (data.clinicCover&&data.branches.length?'<div class="review-group"><h3>Add Clinic / Branch</h3>'+data.branches.map(b=>'<dl class="review-details review-branch">'+row('Clinic name/ Branch name',b.name)+row('Clinic Address',b.address)+row('Phone number',b.phone)+'</dl>').join('')+'</div>':'');
 const org=!!data.clinicCover;
 const declarations='<details class="review-declarations"><summary>Review declarations</summary><dl class="review-details">'+(org?organisationQuestions:individualQuestions).map((q,i)=>row(q,data.answers[(org?'qOrg':'q')+i])).join('')+((org?data.orgDetails:hasRisk()&&data.riskDetails)?row('Please provide details below',org?data.orgDetails:data.riskDetails):'')+'</dl></details>';
 const payment='<fieldset class="review-payment"><legend>Choose anyone of the payment option below:</legend><div class="choices">'+['Credit/Debit Card/Wallet/Personal Internet Banking','Business Internet Banking'].map(v=>'<label class="choice wide"><input type="radio" name="payment" value="'+v+'" '+(data.payment===v?'checked':'')+'>'+v+'</label>').join('')+'</div>'+errorFor('payment')+'</fieldset><p class="hint payment-status" id="payment-availability">'+(samplePricing?'Sample payment · No money will be charged.':'Your premium will appear here when quotation services are available. Payment is not available yet.')+'</p><div id="form-status"></div>';
 return '<div class="review-sections">'+section('coverage','Your coverage','edit-coverage',coverage)+section('personal','Your details','edit-personal',personal)+section('practice','Practice details','edit-personal',practice)+section('declarations','Declaration & Signature','edit-declaration',declarations)+section('payment','Payment','',payment)+'</div>'+actionBar(back(),next('Proceed to payment','payment'));
}
function stateScreen(){if(activeState==='supplementary')return `<div class="card"><div class="card-body">${head('Supplementary questions','file')}<p class="review-only-note">Source content retained for review. The existing API must determine whether these sections are required.</p>${supplementary.map((s,j)=>`<details class="disclosure" ${j===0?'open':''}><summary>${s.title}</summary><div class="disclosure-body">${s.questions.map((q,i)=>typeof q==='string'?question('qSupp'+j+'_'+i,q):`<div class="field" style="margin:20px 0"><label for="supp${j}_${i}">${q.text}</label><textarea id="supp${j}_${i}" name="supp${j}_${i}">${esc(data['supp'+j+'_'+i])}</textarea></div>`).join('')}</div></details>`).join('')}<div class="divider"></div>${check('suppDeclaration','The Applicant declares that, after enquiry, to the best knowledge of all persons to be insured the statements set forth herein and if any attachments made hereto are true, and no material facts have been suppressed, omitted, or misstated.')}</div>${actionBar(back(),next('Next','return-declaration'))}</div>`;
if(activeState==='otp')return `<div class="card state-card"><div class="state-icon">${icon('phone',28)}</div><h2>Verification</h2><p>Please enter your registered mobile number</p><div class="fields" style="max-width:360px;margin:auto">${field('verifyMobile','Mobile number',{type:'tel',placeholder:'+60',full:true})}</div><button type="button" class="btn primary" data-action="otp-request">Message OTP</button> <button type="button" class="btn secondary" data-action="otp-request">Whatsapp OTP</button><div class="divider"></div><label class="field-label" for="otp">Please enter OTP which is sent to your mobile number with in 5 minute</label><input class="otp-input" id="otp" name="otp" maxlength="6" inputmode="numeric" autocomplete="one-time-code" aria-label="One time password"><button type="button" class="btn navy" data-action="otp-verify">Verify</button><div id="form-status"></div></div>`;
const s=states[activeState]||states.error;return `<div class="card state-card"><div class="state-icon">${icon(activeState==='error'?'info':'file',28)}</div><h2>${s.title}</h2><p>${s.message}</p><div class="notice">${icon('info',18)}<span>Screen review only. This outcome has not occurred and no information has been submitted.</span></div><div style="margin-top:24px">${activeState==='support'?'<button type="button" class="btn primary" data-action="support">Yes</button> <button type="button" class="btn secondary" data-action="return-personal">No</button>':'<button type="button" class="btn secondary" data-action="edit-coverage">Back to coverage</button>'}</div><div id="form-status"></div></div>`;}
function render(focus=false){
 data.end=data.start?dateText(endDate()):'';
 const stepMarkup=stages.map((s,i)=>`<button type="button" aria-label="Step ${i+1}: ${s}" class="step ${i<stage?'complete':''}" data-stage="${i}" ${i===stage?'aria-current="step"':''} ${!samplePricing&&i>maxStage?'disabled':''}><span class="step-num">${i<stage?icon('check',14):String(i+1).padStart(2,'0')}</span><span class="step-label"><small>Step ${i+1}</small><span>${s}</span></span></button>`).join('');
 const title=activeState?activeState==='supplementary'?'Additional information':activeState==='otp'?'Verification':'Application status':['Your coverage','Your quotation','Personal particulars','Declaration','Review your application'][stage];
 
 $('#main').innerHTML=`${samplePricing?`<details class="review-tools"><summary>Interface review <span>Browse screens and states</span>${icon('plus',14)}</summary><div class="review-toolbar"><button type="button" data-action="sample-fill">Fill sample details</button><a href="services.html?flow=renewal&sample=1">Preview renewal</a><a href="services.html?flow=claims&sample=1">Preview claims</a>${stages.map((s,i)=>`<button type="button" data-stage="${i}">${s}</button>`).join('')}<button type="button" data-state="supplementary">Additional questions</button><button type="button" data-state="otp">OTP</button><button type="button" data-state="support">Referral</button><button type="button" data-state="quoteSent">Email outcome</button><button type="button" data-state="expired">Expired</button><button type="button" data-state="error">Error</button><a href="design-system.html" target="_blank">Component library ↗</a><p>Sample journey. No applications, messages or payments are submitted.</p></div></details>`:''}<div class="layout" data-step="${stage}">${sidebar()}<section class="form-column stage-${stage}" aria-labelledby="page-title"><form id="application-form" novalidate><div class="page-heading"><p class="page-progress"><span>${stage+1} / 5</span><span>${stages[stage]}</span></p><h1 id="page-title">${title}</h1></div>${errorSummary()}${activeState?stateScreen():[coverage,quotation,personal,declarations,reviewScreen][stage]()}</form><div class="form-help">${icon('phone',14)}<span>Contact Us</span><a href="https://wa.me/60125360700" target="_blank" rel="noopener">+60 12-536 0700 ↗</a></div></section></div>`;
 $('#stepper').innerHTML=stepMarkup;
 if(focus){$('#main').focus();window.scrollTo({top:0,behavior:'instant'});}
 $('#announcement').textContent=title;if(samplePricing){const status=$('#draft-status');if(status){status.textContent='Design preview';status.dataset.state='preview';}}persist();
}
function errorLabel(id){const labels={classification:'Classification',liability:'Limit Of Liability',start:'Insurance Start Date',email:'Your Email',consent:'Terms and conditions',allocations:'Service Details',clinic:'Clinic ownership',ownership:'Ownership type',locum:'Locum practice',picAny:'PIC for any clinic',picOther:'PIC with another establishment',clinicLiability:'Clinic Limit Of Liability',nationality:'Nationality',otherNationality:'Country name',clinicName:'Clinic name',branchAgreement:'Branch indemnity agreement',pic:'PIC coverage',fullName:'Full Name as per IC',dob:'Date Of Birth',nric:'NRIC Number',practice:'Primary location of Practice',mobile:'Mobile Number',declaration:'Declaration and Authorization',riskDetails:'Disclosure details',orgDetails:'Clinic disclosure details',payment:'Payment option'};return labels[id]||(id.startsWith('qOrg')?'Clinic declaration '+(Number(id.slice(4))+1):id.startsWith('q')?'Declaration '+(Number(id.slice(1))+1):id);}
function errorSummary(){const entries=Object.entries(errors).filter(([,v])=>v);return entries.length?`<div class="error-summary" role="alert" tabindex="-1"><strong>Please review ${entries.length===1?'this field':entries.length+' fields'} before continuing.</strong><ul>${entries.map(([id,message])=>`<li><button type="button" data-error-target="${id}">${esc(errorLabel(id))}: ${esc(message)}</button></li>`).join('')}</ul></div>`:'';}
function go(i){stage=i;activeState=null;errors={};maxStage=Math.max(maxStage,i);render(true);}
function showErrors(){render();const first=Object.keys(errors)[0];const target=document.getElementById(first)||document.querySelector(`[name="${first}"]`);target?.focus();target?.scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});$('#announcement').textContent='Please review the highlighted fields.';}
function validCoverage(){errors=validateCoverage(data);return !Object.keys(errors).length;}
function validPersonal(){errors=validatePersonal(data);return !Object.keys(errors).length;}
function validDeclarations(){errors=validateDeclarations(data);return !Object.keys(errors).length;}
let pendingOperation=false;
async function boundary(operation){
 if(samplePricing){if(operation==='createPayment'){modal('Sample payment','<p>No money will be charged. Choose an outcome to preview.</p>','<button type="button" class="btn primary" data-action="sample-paid">Successful payment</button><button type="button" class="btn secondary" data-action="sample-failed">Failed payment</button><button type="button" class="btn secondary" data-action="sample-pending">Pending payment</button>');}else modal('Sample outcome','<p>'+ (operation==='emailQuote'?'Quotation email preview completed. No email was sent.':operation==='requestOtp'?'Sample OTP: 123456. No message was sent.':'Preview completed. No information was submitted.')+'</p>');return;}
 if(pendingOperation)return;
 pendingOperation=true;
 const status=$('#form-status');
 const trigger=document.activeElement;
 const actionable=trigger?.tagName==='BUTTON';
 if(actionable){trigger.disabled=true;trigger.setAttribute('aria-busy','true');}
 if(status)status.innerHTML=notice('<p>Connecting…</p>',{live:true});
 try{await insuranceApi[operation]();}
 catch(error){
  if(status){status.innerHTML=notice('<p>'+esc(error.message)+'</p>',{tone:'error',title:'This service is not available yet',live:true});status.scrollIntoView({block:'nearest',behavior:'smooth'});}
  else modal('Service unavailable','<p>'+esc(error.message)+'</p>');
 }finally{pendingOperation=false;if(actionable){trigger.disabled=false;trigger.removeAttribute('aria-busy');}}
}
let previousFocus;
function modal(title,body,footer=''){previousFocus=document.activeElement;$('#modal-content').innerHTML=`<div class="modal-head"><h2 id="modal-title">${title}</h2><button type="button" class="icon-btn" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${body}</div><div class="modal-footer">${footer||'<span></span><button type="button" class="btn secondary" data-action="close-modal">Close</button>'}</div>`;document.body.classList.add('modal-open');$('#modal').showModal();}
$('#modal').addEventListener('close',()=>{document.body.classList.remove('modal-open');$('#modal').classList.remove('premium-dialog','allocation-dialog');document.body.classList.remove('premium-modal-open');if(previousFocus?.isConnected)previousFocus.focus();});
$('#modal').addEventListener('click',event=>{if(event.target!==$('#modal')||!$('#modal').classList.contains('premium-dialog'))return;const r=$('#modal').getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)$('#modal').close();});
const total=alloc=>Math.round(Object.values(alloc).reduce((a,v)=>a+(Number(v)||0),0)*100)/100;
let allocationDraft={};
function openAllocations(){
 allocationDraft={...data.allocations};
 modal('Specialisations',`<p class="allocation-instruction">Select your specialisations and allocate 100% of your practice.</p><div class="allocation-workspace"><div class="allocation-browser"><div class="allocation-search field"><label for="specialisation-search"><span class="task-marker" aria-hidden="true">1</span>Search specialisations</label><div class="input-icon"><input id="specialisation-search" type="search" placeholder="Search by name" autocomplete="off">${icon('search',18)}</div></div><div class="allocation-list" id="allocation-list"></div></div><section class="allocation-selected" aria-labelledby="selected-title"><div class="allocation-selected-head"><h3 id="selected-title"><span class="task-marker" aria-hidden="true">2</span>Your selection <span id="allocation-count" class="selection-count"></span></h3><button type="button" class="link-btn" data-action="distribute-allocations">Split equally</button></div><div id="allocation-selected-list"></div></section></div><p class="error" id="allocation-error" role="alert"></p>`,`<div class="allocation-meter"><div><span>Total allocated</span><strong id="allocation-total">0%</strong></div><progress id="allocation-progress" max="100" value="0" aria-label="Practice allocated"></progress><span id="allocation-remaining" role="status"></span></div><div><button type="button" class="btn secondary" data-action="reset-allocations">Reset</button><button type="button" class="btn primary" data-action="save-allocations">Save specialisations</button></div>`);
 $('#modal').classList.add('allocation-dialog');renderAllocationRows('');renderSelectedAllocations();
}
function renderAllocationRows(query){
 const list=(configuration(data)?.specialisations||[]).map((s,i)=>({s,i})).filter(({s})=>s.toLowerCase().includes(query.toLowerCase()));
 $('#allocation-list').innerHTML=list.length?list.map(({s,i})=>`<label class="specialisation-option"><input type="checkbox" data-specialisation="${i}" ${Object.hasOwn(allocationDraft,i)?'checked':''}><span>${esc(s)}</span>${icon('plus',16)}</label>`).join(''):'<p class="allocation-empty">No specialisations found.</p>';
}
function renderSelectedAllocations(){
 const names=configuration(data)?.specialisations||[];
 $('#allocation-selected-list').innerHTML=Object.keys(allocationDraft).length?Object.entries(allocationDraft).map(([i,v])=>`<div class="selected-allocation"><label for="allocation-${i}">${esc(names[i])}</label><div class="allocation-value"><input type="number" min="0.01" max="100" step="0.01" inputmode="decimal" id="allocation-${i}" data-allocation="${i}" value="${v||''}" placeholder="0" aria-label="${esc(names[i])} Percentage(%)"><span>%</span></div><button type="button" class="icon-btn" data-action="remove-allocation" data-index="${i}" aria-label="Remove ${esc(names[i])}">${icon('close',16)}</button></div>`).join(''):'<p class="allocation-empty">Select a specialisation to add its percentage.</p>';
 updateAllocationTotal();
}
function updateAllocationTotal(){
 const amount=allocationTotal(allocationDraft),remaining=Math.round((100-amount)*100)/100;
 $('#allocation-count').textContent=Object.keys(allocationDraft).length;
 $('#allocation-total').textContent=amount+'%';$('#allocation-progress').value=Math.min(100,amount);
 $('#allocation-remaining').textContent=remaining<0?Math.abs(remaining)+'% over allocated':remaining>0?remaining+'% remaining':'100% allocated';
 $('#allocation-remaining').classList.toggle('error',remaining<0);
 document.querySelector('[data-action="distribute-allocations"]').disabled=!Object.keys(allocationDraft).length;
 $('#allocation-error').textContent='';document.querySelectorAll('[data-allocation]').forEach(input=>{input.removeAttribute('aria-invalid');input.removeAttribute('aria-describedby');});
}

let branchIndex=-1;
function branchModal(i=-1){branchIndex=i;const b=data.branches[i]||{};modal('Add Clinic / Branch',`<div class="fields"><div class="field full"><label for="branch-name">Clinic name/ Branch name</label><input id="branch-name" placeholder="e.g Klinik Damansara" value="${esc(b.name)}"></div><div class="field full"><label for="branch-address">Clinic Address</label><textarea id="branch-address" placeholder="ex. 2, angaksaraya jin amang, Kuala Lumpur">${esc(b.address)}</textarea></div><div class="field full"><label for="branch-phone">Phone number</label><input id="branch-phone" type="tel" placeholder="+60" value="${esc(b.phone)}"></div></div><p class="hint">*All fields are required.</p><p class="error" id="branch-error" role="alert"></p>`,`<button type="button" class="btn secondary" data-action="close-modal">Cancel</button><button type="button" class="btn primary" data-action="save-branch">${i<0?'Add Clinic / Branch':'Save changes'}</button>`);}
document.addEventListener('input',e=>{const t=e.target;if(t.id==='specialisation-search'){renderAllocationRows(t.value);return;}if(t.dataset.allocation!==undefined){allocationDraft[t.dataset.allocation]=Number(t.value);updateAllocationTotal();return;}if(t.name){maxStage=Math.min(maxStage,stage);if(stage<3)data.declaration=false;if(t.name.startsWith('q'))data.answers[t.name]=t.value;else data[t.name]=t.type==='checkbox'?t.checked:t.value;}if(t.name==='start'){$('#end').value=data.start?dateText(endDate()):'';if($('#summary-period'))$('#summary-period').textContent=data.start?`${dateText(data.start)} – ${dateText(endDate())}`:'—';}if(t.name==='liability'&&$('#summary-liability'))$('#summary-liability').textContent=t.value||'—';persist();});
document.addEventListener('change',e=>{
 if(e.target.dataset.specialisation!==undefined){const key=e.target.dataset.specialisation;if(e.target.checked)allocationDraft[key]=0;else delete allocationDraft[key];renderSelectedAllocations();return;}

 const t=e.target,name=t.name,value=t.value;if(!name)return;
 if(name.startsWith('q'))data.answers[name]=value;else data[name]=t.type==='checkbox'?t.checked:value;
 const branching=['classification','clinic','ownership','locum','picAny','picOther','clinicCover'];
 if(branching.includes(name)){resetClinicDependents(data,name);maxStage=Math.min(maxStage,name==='classification'?0:1);errors={};}
 if(name==='classification'){data.liability='';data.allocations={};data.nric='';data.patients='';data.revenue='';}
 if(name==='nric'&&/^\d{12}$/.test(value)){data.nationality='Malaysia';data.otherNationality='';}
 if(name==='nationality'&&value!=='Others')data.otherNationality='';
 if(name.startsWith('q')){data.declaration=false;maxStage=Math.min(maxStage,3);}
 if(branching.includes(name)||['nationality','nric','intent','picCover'].includes(name)||name.startsWith('q')&&!name.startsWith('qSupp')){
  render();[...document.getElementsByName(name)].find(el=>el.value===value)?.focus();
  if(name==='classification'&&configuration(data)?.specialist)openAllocations();
 }
});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='application-form')e.target.querySelector('.card-actions .primary, .premium-navigation .primary')?.click();});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.errorTarget){const target=document.getElementById(b.dataset.errorTarget)||document.getElementsByName(b.dataset.errorTarget)[0];target?.focus();target?.scrollIntoView({block:'center'});return;}if(b.dataset.stage!==undefined){const n=Number(b.dataset.stage);if(n>stage&&!samplePricing){errors=[validateCoverage,validateQuotation,validatePersonal,validateDeclarations][stage]?.(data)||{};if(Object.keys(errors).length){showErrors();return;}}if(samplePricing||n<=maxStage)go(n);return;}if(b.dataset.state){activeState=b.dataset.state;errors={};render(true);return;}switch(b.dataset.action){
case 'sample-fill':if(samplePricing){data.classification||='General Medical Practitioner';const config=configuration(data);data.liability||=config.limits[0];data.start||=new Date().toLocaleDateString('en-CA');data.email||='alex@example.com';data.consent=true;if(config.specialist&&!Object.keys(data.allocations).length)data.allocations={0:100};Object.assign(data,{fullName:data.fullName||'Alex Tan',dob:data.dob||'1985-06-15',nationality:data.nationality||'Malaysia',nric:data.nric||'850615101234',practice:data.practice||'Sample Clinic, Kuala Lumpur',mobile:data.mobile||'0123456789',clinicName:data.clinicName||'Sample Clinic',declaration:true});data.clinic||='No';data.picAny||='No';data.ownership||='Partnership / Sdn Bhd';data.locum||='No';data.picOther||='No';data.clinicLiability||=config.limits[0];for(let i=0;i<4;i++){data.answers['q'+i]||=i===0?'Agree':'No';data.answers['qOrg'+i]||='No';}data.riskDetails||='Sample disclosure for preview.';data.orgDetails||='Sample disclosure for preview.';errors={};maxStage=4;render();}break;
case 'sample-paid':if(samplePricing)modal('Sample payment successful','<p>Sample reference: SAMPLE-DS-001. No payment was taken and no policy was issued.</p>');break;
case 'sample-failed':if(samplePricing)modal('Sample payment failed','<p>No payment was taken. Close this dialog to try another payment option.</p>');break;
case 'sample-pending':if(samplePricing)modal('Sample payment pending','<p>No payment was taken. This previews a payment awaiting confirmation.</p>');break;
case 'start-again':modal('Start a new application?','<p>This clears the details saved in this browser tab. You cannot undo this action.</p>','<button type="button" class="btn secondary" data-action="close-modal">Keep my application</button><button type="button" class="btn primary" data-action="clear-application">Clear application</button>');break;
case 'clear-application':clearDraft(draftStorage);location.href=location.pathname;break;
case 'calculate':if(!validCoverage()){showErrors();break;}go(1);break;
case 'next':if(stage===1){errors=validateQuotation(data);if(Object.keys(errors).length){showErrors();break;}if(data.intent!=='Buy now'){await boundary('emailQuote');break;}go(2);}else if(stage===2){if(!validPersonal()){showErrors();break;}go(3);}else if(stage===3){if(!validDeclarations()){showErrors();break;}go(4);}break;
case 'back':if(activeState){activeState=null;render(true);}else go(Math.max(0,stage-1));break;
case 'return-declaration':case 'edit-declaration':go(3);break;case 'edit-coverage':go(0);break;case 'edit-personal':case 'return-personal':go(2);break;
case 'payment':{const allErrors={...validateCoverage(data),...validateQuotation(data),...validatePersonal(data),...validateDeclarations(data)};if(Object.keys(allErrors).length){modal('Review your application','<p>Some required information has changed. Please return to Coverage and complete each step before proceeding.</p>');break;}}if(!data.payment){errors.payment='Select a payment option.';showErrors();break;}await boundary('createPayment');break;
case 'allocations':openAllocations();break;
case 'reset-allocations':allocationDraft={};renderAllocationRows($('#specialisation-search').value);renderSelectedAllocations();break;
case 'distribute-allocations':allocationDraft=distributeAllocations(allocationDraft);renderSelectedAllocations();break;
case 'remove-allocation':delete allocationDraft[b.dataset.index];renderAllocationRows($('#specialisation-search').value);renderSelectedAllocations();$('#specialisation-search').focus();break;
case 'save-allocations':if(!validAllocations(allocationDraft)){$('#allocation-error').textContent='Enter a percentage for each selected specialisation. The total must be 100%.';const inputs=[...document.querySelectorAll('[data-allocation]')];const invalid=inputs.filter(input=>!Number.isFinite(Number(input.value))||Number(input.value)<=0||Number(input.value)>100);(invalid.length?invalid:inputs).forEach(input=>{input.setAttribute('aria-describedby','allocation-error');input.setAttribute('aria-invalid','true');});(invalid[0]||inputs[0]||$('#specialisation-search')).focus();$('#allocation-error').scrollIntoView({block:'nearest'});break;}data.allocations={...allocationDraft};maxStage=0;data.declaration=false;$('#modal').close();render();document.querySelector('[data-action="allocations"]')?.focus();break;
case 'premium-breakdown':modal('Premium breakdown',premiumBreakdown(currentQuote()));$('#modal').classList.add('premium-dialog');document.body.classList.add('premium-modal-open');break;
case 'close-modal':$('#modal').close();break;
case 'branch':branchModal();break;case 'edit-branch':branchModal(Number(b.dataset.index));break;
case 'save-branch':{const branch={name:$('#branch-name').value.trim(),address:$('#branch-address').value.trim(),phone:$('#branch-phone').value.trim()};if(Object.values(branch).some(v=>!v)||!/^\+?[\d\s()-]{8,18}$/.test(branch.phone)){$('#branch-error').textContent='Complete all fields and enter a valid phone number.';break;}if(branchIndex<0&&data.branches.length<4)data.branches.push(branch);else if(branchIndex>=0)data.branches[branchIndex]=branch;$('#modal').close();render();document.querySelector('[data-action="branch"]')?.focus();break;}
case 'remove-branch':data.branches.splice(Number(b.dataset.index),1);render();document.querySelector(data.branches.length?'[data-action="branch"]':'.branch-disclosure > summary')?.focus();break;
case 'declaration':modal('Important Notices to the Applicants',`<div class="legal-copy">${disclosureHtml}</div>`);break;
case 'documents':modal('Policy documents',`<div class="document-list">${[
 {title:'Product Disclosure Sheet (English)',href:'https://my-individualindemnity.doctorshield.com/assets/Product_Disclosure_Sheet_English.pdf',type:'PDF'},
 {title:'Product Disclosure Sheet (Malay)',href:'https://my-individualindemnity.doctorshield.com/assets/Product_Disclosure_Sheet_Malay.pdf',type:'PDF'},
 {title:'DoctorShield User Guide',href:'https://my-individualindemnity.doctorshield.com/assets/DoctorShield_User_Guide.pdf',type:'PDF'},
 {title:'FAQ',href:'https://my.doctorshield.com/resources/faqs'}
 ].map(documentRow).join('')}</div><p class="hint">The applicable Policy Wording is supplied with your quotation. It is not available until a quote has been issued.</p>`);break;
case 'addon-info':modal('Why is this recommended?','<p>Please refer to the Policy Wording for the full details of benefits, exclusions, terms and conditions.</p><p class="hint">The existing service must supply the exact recommendation explanation and eligibility rules before release.</p>');break;
case 'otp-request':await boundary('requestOtp');break;case 'otp-verify':await boundary('verifyOtp');break;case 'support':await boundary('requestSupport');break;
}});
render();

// Recheck only a previously invalid field after editing; preserve focus and input state.
document.addEventListener('focusout',event=>{
 const control=event.target,id=control.name;
 if(!id||!errors[id]||!control.closest('#application-form'))return;
 const validate=[validateCoverage,validateQuotation,validatePersonal,validateDeclarations][stage];
 if(!validate||validate(data)[id])return;
 delete errors[id];
 const group=control.closest('.field,.question,.check-row');
 group?.classList.remove('has-error');
 group?.querySelectorAll('[aria-invalid]').forEach(el=>el.removeAttribute('aria-invalid'));
 document.getElementById(id+'-error')?.remove();
 group?.querySelectorAll('[aria-describedby]').forEach(el=>{
  const ids=el.getAttribute('aria-describedby').split(' ').filter(value=>value!==id+'-error');
  if(ids.length)el.setAttribute('aria-describedby',ids.join(' '));else el.removeAttribute('aria-describedby');
 });
 const summary=document.querySelector('.error-summary');
 if(summary)summary.outerHTML=errorSummary();
});

if(samplePricing)document.querySelectorAll('.header-nav a').forEach(a=>{if(a.getAttribute('href')?.startsWith('services.html'))a.href+='&sample=1';});
if(samplePricing&&new URLSearchParams(location.search).get('renewal')==='1'){Object.assign(data,{classification:'General Medical Practitioner',liability:'RM 500,000',fullName:'Alex Tan',dob:'1985-06-15',email:'alex@example.com',mobile:'0123456789',nationality:'Malaysia',practice:'Sample Clinic, Kuala Lumpur',start:new Date().toLocaleDateString('en-CA')});render();}

